import static functions.RoutingNodesChangedObserver_shardInitialized;

// Notify that the shard that was previously unassigned (`shardA`) is now initializing (`shardB`)
RoutingNodesChangedObserver_shardInitialized(
    new java.util.HashMap<String, String>() {{
        put("unassignedShard", "shardA");
        put("initializedShard", "shardB");
    }}
